  1	package com.posadamareaita;
  2	
  3	import com.posadamareaita.api.Api;
  4	import com.posadamareaita.database.Database;
  5	import io.javalin.Javalin;
  6	
  7	public class Main {
  8	    public static void main(String[] args) throws Exception {
  9	        // Get environment variables
 10	        String dbUrl = System.getenv("DB_URL");
 11	        String dbUser = System.getenv("DB_USER");
 12	        String dbPassword = System.getenv("DB_PASSWORD");
 13	        String portStr = System.getenv("PORT");
 14	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 15	
 16	        // Initialize database
 17	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 18	            throw new IllegalArgumentException("Missing database configuration");
 19	        }
 20	
 21	        Database.initialize(dbUrl, dbUser, dbPassword);
 22	
 23	        // Start server
 24	        Javalin app = Javalin.create()
 25	                .start(port);
 26	
 27	        // Setup routes
 28	        Api.setupRoutes(app);
 29	
 30	        System.out.println("Server started on port " + port);
 31	    }
 32	}
 33	package com.posadamareaita.api;
 34	
 35	import com.google.gson.Gson;
 36	import com.google.gson.JsonObject;
 37	import com.posadamareaita.domain.Reservation;
 38	import com.posadamareaita.domain.Room;
 39	import com.posadamareaita.repository.MessageRepository;
 40	import com.posadamareaita.repository.ReservationRepository;
 41	import com.posadamareaita.repository.RoomRepository;
 42	import com.posadamareaita.service.DocumentService;
 43	import com.posadamareaita.service.ReportService;
 44	import com.posadamareaita.service.ReservationService;
 45	import io.javalin.Javalin;
 46	import io.javalin.http.Context;
 47	import java.math.BigDecimal;
 48	import java.time.LocalDate;
 49	import java.time.YearMonth;
 50	import java.time.format.DateTimeFormatter;
 51	import java.util.HashMap;
 52	import java.util.List;
 53	import java.util.Map;
 54	import java.util.Optional;
 55	
 56	public class Api {
 57	    private static final Gson gson = new Gson();
 58	    private static final DateTimeFormatter dateFormatter = DateTimeFormatter.ISO_LOCAL_DATE;
 59	
 60	    public static void setupRoutes(Javalin app) {
 61	        app.get("/rooms", Api::getRooms);
 62	        app.post("/reservations", Api::createReservation);
 63	        app.get("/reservations/{id}", Api::getReservation);
 64	        app.post("/reservations/{id}/confirmation", Api::confirmReservation);
 65	        app.post("/reservations/{id}/cancellation", Api::cancelReservation);
 66	        app.post("/reservations/{id}/check-in", Api::checkInReservation);
 67	        app.post("/reservations/{id}/check-out", Api::checkOutReservation);
 68	        app.get("/reservations/{id}/document", Api::getDocument);
 69	        app.get("/messages", Api::getMessages);
 70	        app.get("/reports/occupancy", Api::getOccupancyReport);
 71	        app.get("/reports/revenue", Api::getRevenueReport);
 72	    }
 73	
 74	    private static void getRooms(Context ctx) throws Exception {
 75	        List<Room> rooms = RoomRepository.findAll();
 76	        ctx.json(rooms.stream().map(r -> new HashMap<String, Object>() {{
 77	            put("number", r.getNumber());
 78	            put("type", r.getType().getDisplayName());
 79	            put("capacity", r.getCapacity());
 80	            put("nightlyRate", r.getNightlyRate());
 81	        }}).toList());
 82	    }
 83	
 84	    private static void createReservation(Context ctx) throws Exception {
 85	        try {
 86	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
 87	
 88	            // Validate required fields
 89	            if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
 90	                !body.has("checkIn") || !body.has("checkOut") || !body.has("guests") || !body.has("ratePlan")) {
 91	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
 92	                return;
 93	            }
 94	
 95	            int roomNumber = body.get("roomNumber").getAsInt();
 96	            String guestName = body.get("guestName").getAsString();
 97	            String guestEmail = body.get("guestEmail").getAsString();
 98	
 99	            LocalDate checkIn = LocalDate.parse(body.get("checkIn").getAsString(), dateFormatter);
100	            LocalDate checkOut = LocalDate.parse(body.get("checkOut").getAsString(), dateFormatter);
101	
102	            int guests = body.get("guests").getAsInt();
103	            String ratePlanStr = body.get("ratePlan").getAsString();
104	
105	            // Validate rate plan
106	            try {
107	                com.posadamareaita.domain.RatePlan.valueOf(ratePlanStr);
108	            } catch (IllegalArgumentException e) {
109	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
110	                return;
111	            }
112	
113	            // Get identification fields
114	            String guestCpf = body.has("guestCpf") && !body.get("guestCpf").isJsonNull() ? body.get("guestCpf").getAsString() : null;
115	            String companyCnpj = body.has("companyCnpj") && !body.get("companyCnpj").isJsonNull() ? body.get("companyCnpj").getAsString() : null;
116	            String companyName = body.has("companyName") && !body.get("companyName").isJsonNull() ? body.get("companyName").getAsString() : null;
117	            String guestPassport = body.has("guestPassport") && !body.get("guestPassport").isJsonNull() ? body.get("guestPassport").getAsString() : null;
118	            String guestCountry = body.has("guestCountry") && !body.get("guestCountry").isJsonNull() ? body.get("guestCountry").getAsString() : null;
119	
120	            Optional<Reservation> result = ReservationService.createReservation(
121	                    roomNumber, guestName, guestEmail, checkIn, checkOut, guests, ratePlanStr,
122	                    guestCpf, companyCnpj, companyName, guestPassport, guestCountry
123	            );
124	
125	            if (result.isEmpty()) {
126	                // Check what went wrong
127	                Optional<Room> room = RoomRepository.findByNumber(roomNumber);
128	                if (room.isEmpty()) {
129	                    ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
130	                } else if (guests > room.get().getCapacity()) {
131	                    ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Too many guests for this room"));
132	                } else if (guests < 1 || !checkOut.isAfter(checkIn)) {
133	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request data"));
134	                } else {
135	                    ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for these dates"));
136	                }
137	                return;
138	            }
139	
140	            ctx.status(201).json(buildReservationResponse(result.get()));
141	        } catch (Exception e) {
142	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
143	        }
144	    }
145	
146	    private static void getReservation(Context ctx) throws Exception {
147	        try {
148	            long id = Long.parseLong(ctx.pathParam("id"));
149	            Optional<Reservation> res = ReservationRepository.findById(id);
150	
151	            if (res.isEmpty()) {
152	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
153	                return;
154	            }
155	
156	            ctx.json(buildReservationResponse(res.get()));
157	        } catch (Exception e) {
158	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
159	        }
160	    }
161	
162	    private static void confirmReservation(Context ctx) throws Exception {
163	        try {
164	            long id = Long.parseLong(ctx.pathParam("id"));
165	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
166	
167	            if (!body.has("amountPaid")) {
168	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing amountPaid"));
169	                return;
170	            }
171	
172	            BigDecimal amountPaid = body.get("amountPaid").getAsBigDecimal();
173	            Optional<Reservation> result = ReservationService.confirm(id, amountPaid);
174	
175	            if (result.isEmpty()) {
176	                Optional<Reservation> res = ReservationRepository.findById(id);
177	                if (res.isEmpty()) {
178	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
179	                } else {
180	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot confirm this reservation"));
181	                }
182	                return;
183	            }
184	
185	            ctx.json(buildReservationResponse(result.get()));
186	        } catch (Exception e) {
187	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
188	        }
189	    }
190	
191	    private static void cancelReservation(Context ctx) throws Exception {
192	        try {
193	            long id = Long.parseLong(ctx.pathParam("id"));
194	            Optional<Reservation> result = ReservationService.cancel(id);
195	
196	            if (result.isEmpty()) {
197	                Optional<Reservation> res = ReservationRepository.findById(id);
198	                if (res.isEmpty()) {
199	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
200	                } else {
201	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot cancel this reservation"));
202	                }
203	                return;
204	            }
205	
206	            ctx.json(buildReservationResponse(result.get()));
207	        } catch (Exception e) {
208	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
209	        }
210	    }
211	
212	    private static void checkInReservation(Context ctx) throws Exception {
213	        try {
214	            long id = Long.parseLong(ctx.pathParam("id"));
215	            Optional<Reservation> result = ReservationService.checkIn(id);
216	
217	            if (result.isEmpty()) {
218	                Optional<Reservation> res = ReservationRepository.findById(id);
219	                if (res.isEmpty()) {
220	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
221	                } else {
222	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot check in this reservation"));
223	                }
224	                return;
225	            }
226	
227	            ctx.json(buildReservationResponse(result.get()));
228	        } catch (Exception e) {
229	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
230	        }
231	    }
232	
233	    private static void checkOutReservation(Context ctx) throws Exception {
234	        try {
235	            long id = Long.parseLong(ctx.pathParam("id"));
236	            Optional<Reservation> result = ReservationService.checkOut(id);
237	
238	            if (result.isEmpty()) {
239	                Optional<Reservation> res = ReservationRepository.findById(id);
240	                if (res.isEmpty()) {
241	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
242	                } else {
243	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot check out this reservation"));
244	                }
245	                return;
246	            }
247	
248	            ctx.json(buildReservationResponse(result.get()));
249	        } catch (Exception e) {
250	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
251	        }
252	    }
253	
254	    private static void getDocument(Context ctx) throws Exception {
255	        try {
256	            long id = Long.parseLong(ctx.pathParam("id"));
257	            Optional<Reservation> opt = ReservationService.getDocument(id);
258	
259	            if (opt.isEmpty()) {
260	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
261	                return;
262	            }
263	
264	            Reservation res = opt.get();
265	            Optional<Room> room = RoomRepository.findByNumber(res.getRoomNumber());
266	            if (room.isEmpty()) {
267	                ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
268	                return;
269	            }
270	
271	            ctx.json(DocumentService.generateDocumentResponse(res, room.get()));
272	        } catch (Exception e) {
273	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
274	        }
275	    }
276	
277	    private static void getMessages(Context ctx) throws Exception {
278	        List<com.posadamareaita.domain.Message> messages = MessageRepository.findAll();
279	        ctx.json(messages.stream().map(m -> new HashMap<String, Object>() {{
280	            put("id", m.getId());
281	            put("channel", m.getChannel());
282	            put("to", m.getTo());
283	            put("subject", m.getSubject());
284	            put("body", m.getBody());
285	        }}).toList());
286	    }
287	
288	    private static void getOccupancyReport(Context ctx) throws Exception {
289	        try {
290	            String dateStr = ctx.queryParam("date");
291	            if (dateStr == null) {
292	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
293	                return;
294	            }
295	
296	            LocalDate date = LocalDate.parse(dateStr, dateFormatter);
297	            String report = ReportService.generateOccupancyReport(date);
298	            ctx.contentType("text/csv; charset=utf-8").result(report);
299	        } catch (Exception e) {
300	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
301	        }
302	    }
303	
304	    private static void getRevenueReport(Context ctx) throws Exception {
305	        try {
306	            String monthStr = ctx.queryParam("month");
307	            if (monthStr == null) {
308	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
309	                return;
310	            }
311	
312	            YearMonth ym = YearMonth.parse(monthStr);
313	            String report = ReportService.generateRevenueReport(ym.getYear(), ym.getMonthValue());
314	            ctx.contentType("text/csv; charset=utf-8").result(report);
315	        } catch (Exception e) {
316	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
317	        }
318	    }
319	
320	    private static Map<String, Object> buildReservationResponse(Reservation res) {
321	        Map<String, Object> response = new HashMap<>();
322	        response.put("id", res.getId());
323	        response.put("roomNumber", res.getRoomNumber());
324	        response.put("guestName", res.getGuestName());
325	        response.put("guestEmail", res.getGuestEmail());
326	        response.put("checkIn", res.getCheckIn().toString());
327	        response.put("checkOut", res.getCheckOut().toString());
328	        response.put("guests", res.getGuests());
329	        response.put("ratePlan", res.getRatePlan().toString());
330	        response.put("nights", res.getNights());
331	        response.put("subtotal", res.getSubtotal());
332	        response.put("discount", res.getDiscount());
333	        response.put("total", res.getTotal());
334	        response.put("status", res.getStatus().toString());
335	        response.put("amountPaid", res.getAmountPaid());
336	        response.put("refund", res.getRefund());
337	        response.put("guestCpf", res.getGuestCpf());
338	        response.put("companyCnpj", res.getCompanyCnpj());
339	        response.put("companyName", res.getCompanyName());
340	        response.put("guestPassport", res.getGuestPassport());
341	        response.put("guestCountry", res.getGuestCountry());
342	        return response;
343	    }
344	}
