180	    private static String buildConfirmationEmail(Reservation res, String documentText) {
181	        StringBuilder sb = new StringBuilder();
182	        sb.append("Olá, ").append(res.getGuestName()).append("!\n\n");
183	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
184	        sb.append(documentText).append("\n");
185	        sb.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
186	        sb.append("Até breve!");
187	        return sb.toString();
188	    }
189	}
