332	public class ReportService {
333	    public static String generateOccupancyReport(LocalDate date) throws Exception {
334	        List<Reservation> reservations = ReservationRepository.findByDateAndStatus(date);
335	        List<Room> rooms = RoomRepository.findAll();
336	
337	        StringBuilder csv = new StringBuilder();
338	        csv.append("room,type,reservation,check_in,check_out\n");
339	
340	        int occupiedCount = 0;
341	        for (Reservation res : reservations) {
342	            Room room = rooms.stream().filter(r -> r.getNumber() == res.getRoomNumber()).findFirst().orElse(null);
343	            if (room != null) {
344	                csv.append(room.getNumber()).append(",");
345	                csv.append(room.getType().getDisplayName()).append(",");
346	                csv.append(res.getId()).append(",");
347	                csv.append(FormattingUtil.formatDateISO(res.getCheckIn())).append(",");
348	                csv.append(FormattingUtil.formatDateISO(res.getCheckOut())).append("\n");
349	                occupiedCount++;
350	            }
351	        }
352	
353	        csv.append("total,").append(occupiedCount).append("/").append(rooms.size()).append("\n");
354	
355	        return csv.toString();
356	    }
357	
358	    public static String generateRevenueReport(int year, int month) throws Exception {
359	        List<Reservation> reservations = ReservationRepository.findByMonthAndStatus(year, month);
360	
361	        StringBuilder csv = new StringBuilder();
362	        csv.append("reservation,room,check_in,check_out,status,amount\n");
363	
364	        BigDecimal total = BigDecimal.ZERO;
365	        for (Reservation res : reservations) {
366	            BigDecimal amount = res.getAmountPaid();
367	            if (res.getRefund() != null) {
368	                amount = amount.subtract(res.getRefund());
369	            }
370	
371	            csv.append(res.getId()).append(",");
372	            csv.append(res.getRoomNumber()).append(",");
373	            csv.append(FormattingUtil.formatDateISO(res.getCheckIn())).append(",");
374	            csv.append(FormattingUtil.formatDateISO(res.getCheckOut())).append(",");
375	            csv.append(res.getStatus().toString()).append(",");
376	            csv.append(String.format("%.2f", amount)).append("\n");
377	
378	            total = total.add(amount);
379	        }
380	
381	        csv.append("total,,,,").append(String.format("%.2f", total)).append("\n");
382	
383	        return csv.toString();
384	    }
385	}

