 16	public class ReservationService {
 17	    public static Optional<Reservation> createReservation(int roomNumber, String guestName, String guestEmail,
 18	                                                          LocalDate checkIn, LocalDate checkOut, int guests,
 19	                                                          String ratePlanStr, String guestCpf, String companyCnpj,
 20	                                                          String companyName, String guestPassport, String guestCountry)
 21	            throws Exception {
 22	
 23	        // Validate identification
 24	        int identificationCount = (guestCpf != null ? 1 : 0) +
 25	                                  (companyCnpj != null ? 1 : 0) +
 26	                                  (guestPassport != null ? 1 : 0);
 27	        if (identificationCount != 1) {
 28	            return Optional.empty();
 29	        }
 30	
 31	        // Validate guests
 32	        if (guests < 1) {
 33	            return Optional.empty();
 34	        }
 35	
 36	        // Validate dates
 37	        if (!checkOut.isAfter(checkIn)) {
 38	            return Optional.empty();
 39	        }
 40	
 41	        // Get room
 42	        Optional<Room> room = RoomRepository.findByNumber(roomNumber);
 43	        if (room.isEmpty()) {
 44	            return Optional.empty();
 45	        }
 46	
 47	        // Check capacity
 48	        if (guests > room.get().getCapacity()) {
 49	            return Optional.empty();
 50	        }
 51	
 52	        // Check availability
 53	        List<Reservation> conflicts = ReservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
 54	        if (!conflicts.isEmpty()) {
 55	            return Optional.empty();
 56	        }
 57	
 58	        // Calculate price
 59	        RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);
 60	        PriceCalculator.PriceResult priceResult = PriceCalculator.calculatePrice(room.get(), checkIn, checkOut, ratePlan);
 61	
 62	        // Create reservation
 63	        Reservation res = new Reservation(roomNumber, guestName, guestEmail, checkIn, checkOut, guests, ratePlan,
 64	                guestCpf, companyCnpj, companyName, guestPassport, guestCountry);
 65	        res.setNights((int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut));
 66	        res.setSubtotal(priceResult.subtotal);
 67	        res.setDiscount(priceResult.discount);
 68	        res.setTotal(priceResult.total);
 69	
 70	        long id = ReservationRepository.create(res);
 71	        res.setId(id);
 72	
 73	        return Optional.of(res);
 74	    }
 75	
 76	    public static Optional<Reservation> confirm(long reservationId, BigDecimal amountPaid) throws Exception {
 77	        Optional<Reservation> opt = ReservationRepository.findById(reservationId);
 78	        if (opt.isEmpty()) {
 79	            return Optional.empty();
 80	        }
 81	
 82	        Reservation res = opt.get();
 83	        if (res.getStatus() != ReservationStatus.PENDING) {
 84	            return Optional.empty();
 85	        }
 86	
 87	        res.setStatus(ReservationStatus.CONFIRMED);
 88	        res.setAmountPaid(amountPaid);
 89	        ReservationRepository.update(res);
 90	
 91	        // Send confirmation email
 92	        Optional<Room> room = RoomRepository.findByNumber(res.getRoomNumber());
 93	        if (room.isPresent()) {
 94	            String documentText;
 95	            if (res.getGuestCpf() != null) {
 96	                documentText = DocumentService.generateReceiptPT(res, room.get());
 97	            } else if (res.getCompanyCnpj() != null) {
 98	                documentText = DocumentService.generateInvoice(res, room.get());
 99	            } else {
100	                documentText = DocumentService.generateBookingReceipt(res, room.get());
101	            }
102	
103	            String emailBody = buildConfirmationEmail(res, documentText);
104	            MessageService.sendEmail(res.getGuestEmail(), "Reserva confirmada - Pousada Maré Alta", emailBody);
105	        }
106	
107	        return Optional.of(res);
108	    }
109	
110	    public static Optional<Reservation> checkIn(long reservationId) throws Exception {
111	        Optional<Reservation> opt = ReservationRepository.findById(reservationId);
112	        if (opt.isEmpty()) {
113	            return Optional.empty();
114	        }
115	
116	        Reservation res = opt.get();
117	        if (res.getStatus() != ReservationStatus.CONFIRMED) {
118	            return Optional.empty();
119	        }
120	
121	        res.setStatus(ReservationStatus.CHECKED_IN);
122	        ReservationRepository.update(res);
123	
124	        return Optional.of(res);
125	    }
126	
127	    public static Optional<Reservation> checkOut(long reservationId) throws Exception {
128	        Optional<Reservation> opt = ReservationRepository.findById(reservationId);
129	        if (opt.isEmpty()) {
130	            return Optional.empty();
131	        }
132	
133	        Reservation res = opt.get();
134	        if (res.getStatus() != ReservationStatus.CHECKED_IN) {
135	            return Optional.empty();
136	        }
137	
138	        res.setStatus(ReservationStatus.CHECKED_OUT);
139	        ReservationRepository.update(res);
140	
141	        return Optional.of(res);
142	    }
143	
144	    public static Optional<Reservation> cancel(long reservationId) throws Exception {
145	        Optional<Reservation> opt = ReservationRepository.findById(reservationId);
146	        if (opt.isEmpty()) {
147	            return Optional.empty();
148	        }
149	
150	        Reservation res = opt.get();
151	        if (res.getStatus() == ReservationStatus.CHECKED_IN ||
152	            res.getStatus() == ReservationStatus.CHECKED_OUT ||
153	            res.getStatus() == ReservationStatus.CANCELLED) {
154	            return Optional.empty();
155	        }
156	
157	        // Calculate refund before changing status
158	        ReservationStatus originalStatus = res.getStatus();
159	        if (originalStatus == ReservationStatus.CONFIRMED) {
160	            if (res.getRatePlan() == RatePlan.STANDARD) {
161	                res.setRefund(res.getAmountPaid());
162	            } else {
163	                res.setRefund(BigDecimal.ZERO);
164	            }
165	        } else {
166	            res.setRefund(BigDecimal.ZERO);
167	        }
168	
169	        res.setStatus(ReservationStatus.CANCELLED);
170	
171	        ReservationRepository.update(res);
172	
173	        return Optional.of(res);
174	    }
