 14	        String sql = """
 15	                INSERT INTO messages (channel, recipient, subject, body)
 16	                VALUES (?, ?, ?, ?)
 17	                """;
 18	        try (Connection conn = Database.getDataSource().getConnection();
 19	             PreparedStatement stmt = conn.prepareStatement(sql, PreparedStatement.RETURN_GENERATED_KEYS)) {
 20	            stmt.setString(1, message.getChannel());
 21	            stmt.setString(2, message.getTo());
 22	            stmt.setString(3, message.getSubject());
