 24	            stmt.executeUpdate();
 25	
 26	            var generatedKeys = stmt.getGeneratedKeys();
 27	            if (generatedKeys.next()) {
 28	                message.setId(generatedKeys.getLong(1));
 29	            }
 30	        }
 31	    }
