   239	public class PriceCalculator {
   240	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
   241	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
   242	
   243	    public static class PriceResult {
   244	        public BigDecimal subtotal;
   245	        public BigDecimal discount;
   246	        public BigDecimal total;
   247	
   248	        public PriceResult(BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
   249	            this.subtotal = subtotal;
   250	            this.discount = discount;
   251	            this.total = total;
   252	        }
   253	    }
   254	
   255	    public static PriceResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
   256	        BigDecimal nightlyRate = room.getNightlyRate();
   257	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
   258	
   259	        // Calculate price per night considering season
   260	        BigDecimal subtotal = BigDecimal.ZERO;
   261	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
   262	            BigDecimal nightPrice = nightlyRate;
   263	            if (SeasonUtil.isHighSeason(date)) {
   264	                nightPrice = nightPrice.multiply(HIGH_SEASON_MULTIPLIER);
   265	            }
   266	            nightPrice = MoneyUtil.round(nightPrice);
   267	            subtotal = subtotal.add(nightPrice);
   268	        }
   269	        subtotal = MoneyUtil.round(subtotal);
   270	
   271	        // Calculate discount
   272	        BigDecimal discount = BigDecimal.ZERO;
   273	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
   274	            discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE);
   275	            discount = MoneyUtil.round(discount);
   276	        }
   277	
   278	        BigDecimal total = subtotal.subtract(discount);
   279	        total = MoneyUtil.round(total);
   280	
   281	        return new PriceResult(subtotal, discount, total);
   282	    }
   283	}
